"use client";

import { useLanguage } from "./language-provider";
import "../app/eigenplot-gallery.css";

type GalleryCase = {
  id: string;
  image: string;
  title: string;
  titleZh: string;
  subtitle: string;
  subtitleZh: string;
  inputs: { label: string; labelZh: string; shape: string }[];
  code: string[];
};

/** Actual screenshots generated by scripts/render-eigenplot-gallery.py. */
export const eigenplotGalleryCases: GalleryCase[] = [
  {
    id: "sphere", image: "/images/eigenplot3d/gallery/sphere.png",
    title: "PlotSphere", titleZh: "PlotSphere · 球体",
    subtitle: "Point clouds with individually sized spheres.",
    subtitleZh: "用球体显示离散采样点，每个球都可以有自己的半径。",
    inputs: [
      { label: "Centers", labelZh: "球心", shape: "(N × 3)" },
      { label: "Radius", labelZh: "半径", shape: "(N,)" },
    ],
    code: [
      "t = np.linspace(0, 4.5*np.pi, 36)",
      "coords = np.c_[.75*np.cos(t), .75*np.sin(t),",
      "               np.linspace(-1, 1, 36)]",
      "radius = .095 + .055*(1 + np.sin(1.3*t))/2",
      "PlotSphere(coords=coords, radius=radius, figure=fig)",
    ],
  },
  {
    id: "rod", image: "/images/eigenplot3d/gallery/rod.png",
    title: "PlotRod", titleZh: "PlotRod · 杆状体",
    subtitle: "Orientable rods for director and alignment fields.",
    subtitleZh: "用杆状体展示取向场，例如液晶指向场和局部排列方向。",
    inputs: [
      { label: "Centers", labelZh: "中心点", shape: "(N × 3)" },
      { label: "Orientations", labelZh: "取向", shape: "(N × 3)" },
    ],
    code: [
      "x, y = np.meshgrid(np.linspace(-1.15, 1.15, 9),",
      "                   np.linspace(-1.15, 1.15, 9))",
      "coords = np.c_[x.ravel(), y.ravel(), np.zeros(x.size)]",
      "phi = .5*np.arctan2(y.ravel(), x.ravel() + .001)",
      "orient = np.c_[np.cos(phi), np.sin(phi),",
      "               .22*np.sin(x.ravel())]",
      "PlotRod(coords=coords, orient=orient, length=.38,",
      "        radius=.037, figure=fig)",
    ],
  },
  {
    id: "vector-variable", image: "/images/eigenplot3d/gallery/vector-variable.png",
    title: "PlotVector", titleZh: "PlotVector · 矢量箭头",
    subtitle: "Display a sampled vector field with directional arrows.",
    subtitleZh: "用箭头展示空间采样点上的矢量场。",
    inputs: [
      { label: "Positions", labelZh: "位置", shape: "(N × 3)" },
      { label: "Directions", labelZh: "方向", shape: "(N × 3)" },
    ],
    code: [
      "x, y = np.meshgrid(np.linspace(-1.55, 1.55, 9),",
      "                   np.linspace(-1.55, 1.55, 9))",
      "coords = np.c_[x.ravel(), y.ravel(), np.zeros(x.size)]",
      "r2 = x.ravel()**2 + y.ravel()**2",
      "orient = np.c_[-y.ravel(), x.ravel(),",
      "               .55 + .75*np.exp(-r2)]",
      "mag = np.linalg.norm(orient, axis=1)",
      "length = .16 + .65*(mag - mag.min())/np.ptp(mag)",
      "PlotVector(coords=coords, orient=orient,",
      "           length=length, radius=.033, figure=fig)",
    ],
  },
  {
    id: "tube", image: "/images/eigenplot3d/gallery/tube.png",
    title: "PlotTube", titleZh: "PlotTube · 管线",
    subtitle: "A continuous tube following an ordered space curve.",
    subtitleZh: "沿空间曲线生成连续管线，半径可以沿路径改变。",
    inputs: [
      { label: "Centerline", labelZh: "中心线", shape: "(N × 3)" },
    ],
    code: [
      "t = np.linspace(0, 4*np.pi, 220)",
      "coords = np.c_[.78*np.cos(t), .78*np.sin(t),",
      "               .42*(t/np.pi - 2)]",
      "radius = .055 + .05*(1 + np.sin(1.2*t))/2",
      "PlotTube(coords=coords, radius=radius, figure=fig)",
    ],
  },
  {
    id: "delaunay", image: "/images/eigenplot3d/gallery/delaunay.png",
    title: "PlotDelaunay", titleZh: "PlotDelaunay · 曲面重建",
    subtitle: "Reconstruct a triangulated surface from sampled points.",
    subtitleZh: "给出曲面上的采样点，由 Delaunay 三角剖分生成曲面。",
    inputs: [
      { label: "Sampled points", labelZh: "采样点", shape: "(N × 3)" },
    ],
    code: [
      "x, y = np.meshgrid(np.linspace(-1.25, 1.25, 30),",
      "                   np.linspace(-1.25, 1.25, 30))",
      "z = .45*np.sin(2.3*x)*np.cos(2.5*y)",
      "z += .18*np.exp(-3*(x*x + y*y))",
      "coords = np.c_[x.ravel(), y.ravel(), z.ravel()]",
      "PlotDelaunay(coords=coords, figure=fig)",
    ],
  },
  {
    id: "polydata", image: "/images/eigenplot3d/gallery/polydata.png",
    title: "PlotPolyData", titleZh: "PlotPolyData · 三角网格",
    subtitle: "Display a mesh with explicitly supplied vertices and faces.",
    subtitleZh: "直接使用顶点与面片的连接关系绘制网格，例如环面。",
    inputs: [
      { label: "Mesh", labelZh: "网格", shape: "PyVista / VTK dataset" },
    ],
    code: [
      "nu, nv = 54, 28",
      "u, v = np.meshgrid(np.arange(nu)*2*np.pi/nu,",
      "                   np.arange(nv)*2*np.pi/nv,",
      "                   indexing='ij')",
      "R, r = .88, .32",
      "x = (R + r*np.cos(v))*np.cos(u)",
      "y = (R + r*np.cos(v))*np.sin(u)",
      "z = r*np.sin(v)",
      "vertices = np.c_[x.ravel(), y.ravel(), z.ravel()]",
      "faces = []",
      "for i in range(nu):",
      "    for j in range(nv):",
      "        a = i*nv+j",
      "        b = ((i+1)%nu)*nv+j",
      "        c = ((i+1)%nu)*nv+(j+1)%nv",
      "        d = i*nv+(j+1)%nv",
      "        faces.extend(((3,a,b,c), (3,a,c,d)))",
      "mesh = pv.PolyData(vertices, np.asarray(faces, dtype=np.int64))",
      "PlotPolyData(polydata=mesh, is_show_edges=True, figure=fig)",
    ],
  },
];

export function EigenplotGallery() {
  const { language } = useLanguage();
  const zh = language === "zh-CN";
  return (
    <section id="eigen-gallery" className="eigen-section eigen-gallery-section">
      <p className="eyebrow">{zh ? "04 / 几何图形展示" : "04 / GALLERY"}</p>
      <h2>{zh ? "目前支持的几何体" : "Supported geometries"}</h2>
      <p className="eigen-gallery-intro">
        {zh
          ? "从离散点和取向矢量，到连续曲线、重建曲面和三角网格。下面的图片都由 EigenPlot3D 实际渲染；展开卡片可查看决定几何形状的输入数据。"
          : "From points and orientations to curves, reconstructed surfaces, and triangle meshes. All images are rendered with EigenPlot3D; expand a card to inspect the geometry inputs."}
      </p>
      <div className="eigen-gallery-grid">
        {eigenplotGalleryCases.map((item, index) => (
          <article className="eigen-gallery-card" key={item.id}>
            <figure>
              <img data-eigen-lightbox loading="lazy" src={item.image} alt={zh ? item.titleZh : item.title} width={900} height={560} />
              <figcaption>{String(index + 1).padStart(2, "0")} / {item.title}</figcaption>
            </figure>
            <div className="eigen-gallery-card-body">
              <h3>{zh ? item.titleZh : item.title}</h3>
              <p>{zh ? item.subtitleZh : item.subtitle}</p>
              <div className="eigen-gallery-geometry">
                <strong className="eigen-gallery-geometry-heading">{zh ? "几何输入" : "Geometry inputs"}</strong>
                {item.inputs.map(input => (
                  <div className="eigen-gallery-input" key={input.label}>
                    <b>{zh ? input.labelZh : input.label}:</b> {input.shape}
                  </div>
                ))}
              </div>
              <details>
                <summary>{zh ? "查看几何生成代码" : "View geometry code"}</summary>
                <pre><code>{item.code.join("\n")}</code></pre>
              </details>
            </div>
          </article>
        ))}
      </div>
      <p className="eigen-gallery-footnote">
        {zh
          ? "代码片段展示关键的几何数据生成步骤，省略了公共导入、PlotFigure 初始化以及配色设置。"
          : "Snippets show the essential geometry construction; shared imports, PlotFigure setup, and colors are omitted."}
      </p>
    </section>
  );
}
